let DATA,SCHEDULE,LEAGUE,ANALYTICS_LOADING,BOX_CACHE=new Map(),PLAYER_SPLIT_CACHE=new Map(),state={season:null,view:'home',search:'',gameDate:'',gamePk:null,playerId:null,playerType:null,returnView:'home',teamFilter:'',teamId:+new URLSearchParams(location.search).get('teamId')||null,leagueFilter:new URLSearchParams(location.search).get('league')||'',qualified:false,saberSide:'hitters',compareType:'hitters',page:{hitters:1,pitchers:1},pageSize:50,visibleCols:{hitters:['name','team','gamesPlayed','plateAppearances','avg','obp','slg','ops','homeRuns','rbi'],pitchers:['name','team','gamesPlayed','gamesStarted','wins','losses','era','fip','inningsPitched','k_pct','whip']},sort:{hitters:{key:'plateAppearances',dir:-1},pitchers:{key:'inningsPitched',dir:-1}}};
const $=s=>document.querySelector(s),fmt=(v,d=1)=>v==null?'—':Number(v).toLocaleString('ja-JP',{maximumFractionDigits:d});
const cols={batters:[['name','選手'],['pa','PA'],['avg','AVG'],['obp','OBP'],['slg','SLG'],['hr','HR'],['so','SO'],['bb','BB'],['avg_ev','EV'],['hard_hit_pct','Hard%'],['barrel_pct','Barrel%'],['xwoba','xwOBA']],pitchers:[['name','投手'],['pitches','投球'],['bf','BF'],['k_pct','K%'],['bb_pct','BB%'],['velo','球速'],['spin','回転'],['whiff_pct','Whiff%'],['csw_pct','CSW%'],['xwoba','xwOBA']],arsenal:[['pitch_name','球種'],['pitches','投球'],['usage_pct','使用%'],['velo','球速'],['spin','回転'],['hbreak','横変化'],['vbreak','縦変化'],['whiff_pct','Whiff%']]};
function rows(key){let source=DATA[key]||(key==='arsenal'?DATA.pitch_types:[])||[];return source.filter(x=>x.season==state.season&&(!state.search||JSON.stringify(x).toLowerCase().includes(state.search.toLowerCase())))}
const analyticsViews=new Set(['overview','arsenal','trends','quality','player']);
async function ensureAnalytics(){if(DATA.batters)return DATA;if(!ANALYTICS_LOADING)ANALYTICS_LOADING=fetch('data/analytics.json').then(r=>{if(!r.ok)throw Error('analytics');return r.json()}).then(full=>DATA=full);return ANALYTICS_LOADING}
function table(key,data=rows(key)){let cs=cols[key];return `<div class="panel"><div class="tablewrap"><table><thead><tr>${cs.map(c=>`<th data-k="${c[0]}">${c[1]}</th>`).join('')}</tr></thead><tbody>${data.map(r=>`<tr>${cs.map(c=>`<td>${c[0]=='name'||c[0]=='pitch_name'?r[c[0]]:fmt(r[c[0]],3)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note">列見出しをタップすると並べ替えできます。</p></div>`}
function overview(){let s=DATA.seasons.find(x=>x.season==state.season)||{};let ks=[['投球数',s.pitches],['試合数',s.games],['投手',s.pitchers],['打者',s.batters],['平均球速',s.avg_velo+' mph'],['平均打球速度',s.avg_ev+' mph'],['Hard-hit率',s.hard_hit_pct+'%'],['Barrel率',s.barrel_pct+'%'],['Whiff率',s.whiff_pct+'%'],['CSW率',s.csw_pct+'%']];return `<div class="kpis">${ks.map(x=>`<div class="kpi"><span>${x[0]}</span><b>${typeof x[1]==='number'?fmt(x[1],2):x[1]}</b></div>`).join('')}</div><div class="grid2"><div class="panel"><h2>球種使用率</h2><div id="pitchChart" class="chart"></div></div><div class="panel"><h2>打者リーダー</h2>${table('batters',rows('batters').sort((a,b)=>b.pa-a.pa).slice(0,15))}</div></div>`}
function gameStatus(g){if(g.status==='Final')return'試合終了';if(g.status==='Live')return`${g.inning_half==='Top'?'表':'裏'} ${g.inning||''}回`;return{'Scheduled':'試合前','Pre-Game':'試合前','Warmup':'試合前','Postponed':'延期','Cancelled':'中止','Suspended':'中断'}[g.detailed_state]||g.detailed_state||'—'}
function gameTime(iso){return iso?new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit'}).format(new Date(iso)):'時刻未定'}
function teamInfo(id,abbr,name){let found=LEAGUE?.standings?.find(x=>x.team_id==id);return{id:id||found?.team_id||0,abbr:abbr||found?.team||name?.split(' ').map(x=>x[0]).join('').slice(0,3).toUpperCase()||'MLB',name:name||found?.name||''}}
function teamBadge(id,abbr,name){let t=teamInfo(id,abbr,name),h=(Number(t.id)*47+19)%360;return `<span class="team-badge" data-team-id="${t.id}" style="--badge-h:${h}" title="${t.name} (${t.abbr})" aria-label="${t.name} (${t.abbr})">${t.abbr}</span>`}
const searchText=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function searchMatches(q){q=searchText(q).trim();if(!q)return[];let seen=new Set(),players=[...(LEAGUE.hitters||[]).map(x=>({...x,resultType:'hitters'})),...(LEAGUE.pitchers||[]).map(x=>({...x,resultType:'pitchers'}))].filter(x=>{let key=`${x.resultType}-${x.id}`;if(seen.has(key))return false;seen.add(key);return searchText(`${x.name} ${x.team} ${x.team_name} ${x.position}`).includes(q)}).sort((a,b)=>Number(b.plateAppearances||b.inningsPitched||0)-Number(a.plateAppearances||a.inningsPitched||0)).slice(0,8);let teams=(LEAGUE.standings||[]).filter(x=>searchText(`${x.team} ${x.name} ${x.division}`).includes(q)).slice(0,4);return [...players,...teams.map(x=>({...x,resultType:'team'}))]}
function showSearchResults(){let box=$('#searchResults'),input=$('#search');if(!box||!input)return;let q=input.value.trim();if(!q){box.innerHTML='';box.classList.remove('open');input.setAttribute('aria-expanded','false');return}let list=searchMatches(q);box.innerHTML=list.length?list.map((x,i)=>x.resultType==='team'?`<button role="option" data-search-team="${x.team}" ${i===0?'data-first-result':''}>${teamBadge(x.team_id,x.team,x.name)}<span><b>${x.name}</b><small>球団 · ${x.league}</small></span></button>`:`<button role="option" data-player="${x.id}" data-type="${x.resultType}" ${i===0?'data-first-result':''}>${teamBadge(x.team_id,x.team,x.team_name)}<span><b>${x.name}</b><small>${x.resultType==='hitters'?'打者':'投手'} · ${x.team} · ${x.position||'—'}</small></span></button>`).join(''):`<div class="search-empty">「${q}」に一致する選手・球団はありません</div>`;box.classList.add('open');input.setAttribute('aria-expanded','true');bindDynamic()}
function lineScore(g){if(!g.innings.length)return'';let heads=g.innings.map(i=>`<th>${i.num}</th>`).join(''),row=side=>g.innings.map(i=>`<td>${i[side]??''}</td>`).join('');return `<div class="tablewrap"><table class="line-score"><thead><tr><th>TEAM</th>${heads}<th>R</th></tr></thead><tbody><tr><td>${g.away.name}</td>${row('away')}<td>${g.away.score??''}</td></tr><tr><td>${g.home.name}</td>${row('home')}<td>${g.home.score??''}</td></tr></tbody></table></div>`}
function gameCard(g,compact=false){let probable=g.away.probable_pitcher||g.home.probable_pitcher?`先発予定: ${g.away.probable_pitcher||'未定'} / ${g.home.probable_pitcher||'未定'}`:'',d=g.decisions||{},decisions=d.winner?`勝: ${d.winner}　敗: ${d.loser||'—'}${d.save?`　S: ${d.save}`:''}`:'';return `<article class="score-card ${compact?'compact-score':''}"><div class="game-meta"><span>${gameTime(g.game_date)} · ${g.venue||'球場未定'}</span><span class="game-status">${gameStatus(g)}</span></div><div class="matchup"><span class="team-with-badge ${g.away.winner?'winner':''}">${teamBadge(g.away.id,g.away.abbreviation,g.away.name)}<span>${g.away.name}</span></span><strong class="team-score">${g.away.score??'–'}</strong><span class="team-with-badge ${g.home.winner?'winner':''}">${teamBadge(g.home.id,g.home.abbreviation,g.home.name)}<span>${g.home.name}</span></span><strong class="team-score">${g.home.score??'–'}</strong></div>${compact?'':lineScore(g)}<div class="game-notes">${[compact?'':probable,decisions].filter(Boolean).join('<br>')}</div><button class="game-detail-btn" data-game="${g.game_pk}">個人成績・詳細を見る →</button></article>`}
function games(){let list=SCHEDULE.dates[state.gameDate]||[];return `<div class="panel"><div class="game-toolbar"><label>試合日 <input type="date" id="gameDate" value="${state.gameDate}" min="${SCHEDULE.start_date}" max="${SCHEDULE.end_date}"></label><span class="games-summary">${list.length}試合</span><span class="note">時刻は日本時間</span></div>${list.length?`<div class="score-grid">${list.map(gameCard).join('')}</div>`:'<div class="empty-games"><h2>この日の試合はありません</h2><p class="note">別の日付を選んでください。</p></div>'}</div>`}
const statFmt=(v,d=3)=>{if(v==null)return'—';if(typeof v!=='number')return v;if(d===2)return v.toFixed(2);if(d===3&&!Number.isInteger(v)){let s=v.toFixed(3);return Math.abs(v)<1?s.replace(/^(-?)0/,'$1'):s}return v.toLocaleString('ja-JP',{maximumFractionDigits:d})};
function playerLeague(x){let t=LEAGUE.standings.find(t=>t.team_id==x.team_id||t.team===x.team),label=`${t?.league||''} ${t?.division||''}`;return label.includes('American')||label.includes('AL')?'AL':label.includes('National')||label.includes('NL')?'NL':''}
function filteredOfficial(type){let data=LEAGUE[type]||[],q=state.search.trim().toLowerCase(),teamGames=Math.max(...LEAGUE.standings.map(x=>x.games||0),1);return data.filter(x=>(!state.teamFilter||x.team===state.teamFilter)&&(!state.leagueFilter||playerLeague(x)===state.leagueFilter)&&(!state.qualified||(type==='hitters'?x.plateAppearances>=teamGames*3.1:Number(x.inningsPitched)>=teamGames))&&(!q||`${x.name} ${x.team} ${x.team_name} ${x.position||''}`.toLowerCase().includes(q)))}
async function openPlayer(id,type){state.playerId=+id;state.playerType=type;state.returnView=state.view;$('#view').innerHTML='<div class="panel loading-state"><b>選手データを読み込み中…</b></div>';await ensureAnalytics();state.view='player';render()}
function leader(title,type,key,digits=3,minKey=null,min=0,ascending=false){let list=filteredOfficial(type).filter(x=>x[key]!=null&&(!minKey||Number(x[minKey])>=min)).sort((a,b)=>(ascending?-1:1)*(Number(b[key])-Number(a[key]))).slice(0,5);return `<div class="leader-card"><h3>${title}</h3>${list.map((x,i)=>`<div class="leader-row"><span class="rank-badge">${i+1}</span><button data-player="${x.id}" data-type="${type}">${teamBadge(x.team_id,x.team,x.team_name)}<span>${x.name}</span></button><span class="metric">${statFmt(x[key],digits)}</span></div>`).join('')}</div>`}
function latestGames(){let dates=Object.keys(SCHEDULE.dates).filter(d=>(SCHEDULE.dates[d]||[]).some(g=>g.status==='Final')).sort(),d=dates.at(-1)||state.gameDate,list=(SCHEDULE.dates[d]||[]).slice(0,8);return `<div class="panel"><div class="section-head"><h2>最新の試合結果</h2><span class="note">${d}</span></div><div class="score-grid">${list.map(g=>gameCard(g,true)).join('')}</div><p><button class="btn" data-go="games" data-date="${d}">この日の全試合を見る</button></p></div>`}
function weeklyMvp(){let w=LEAGUE.weekly||{hitters:[],pitchers:[]},hitters=[...w.hitters].filter(x=>x.plateAppearances>=12).sort((a,b)=>(b.ops-a.ops)||(b.homeRuns-a.homeRuns)||(b.rbi-a.rbi)).slice(0,5),pitchers=[...w.pitchers].filter(x=>Number(x.inningsPitched)>=3).map(x=>({...x,mvpScore:Number(x.inningsPitched)*3+(x.strikeOuts||0)*2+(x.wins||0)*5+(x.saves||0)*5-(x.earnedRuns||0)*4-(x.baseOnBalls||0)})).sort((a,b)=>b.mvpScore-a.mvpScore).slice(0,5),card=(title,type,list,stats)=>`<div class="panel weekly-card"><h3>${title}</h3>${list.map((x,i)=>`<button class="weekly-player" data-player="${x.id}" data-type="${type}"><span class="weekly-rank">${i+1}</span>${teamBadge(x.team_id,x.team,x.team_name)}<span><b>${x.name}</b><small>${stats(x)}</small></span></button>`).join('')}</div>`;return `<div class="section-head"><div><h2>週間MVP候補</h2><span class="note">${w.start_date||'—'}〜${w.end_date||'—'} · 当サイト独自集計</span></div></div><div class="weekly-grid">${card('打者', 'hitters',hitters,x=>`${x.hits||0}安打 · ${x.homeRuns||0}本 · OPS ${statFmt(x.ops,3)}`)}${card('投手','pitchers',pitchers,x=>`${statFmt(x.inningsPitched,1)}回 · ${x.strikeOuts||0}奪三振 · ERA ${statFmt(x.era,2)}`)}</div><p class="note mvp-note">打者は12打席以上のOPS、本塁打、打点順。投手は投球回・奪三振・勝利・セーブと失点・四球から算出した独自スコアです。MLB公式表彰ではありません。</p>`}
function divisionSnapshot(){let leaders=LEAGUE.standings.filter(x=>x.rank===1).sort((a,b)=>a.division.localeCompare(b.division));return `<div class="panel dashboard-standings"><div class="section-head"><div><span class="eyebrow">STANDINGS</span><h2>地区首位</h2></div><button class="text-link" data-go="standings">全順位を見る →</button></div><div class="division-list">${leaders.map(x=>`<div><span>${x.division.replace('American League ','AL ').replace('National League ','NL ')}</span><span class="team-with-badge">${teamBadge(x.team_id,x.team,x.name)}<b>${x.team}</b></span><strong>${x.wins}-${x.losses}</strong></div>`).join('')}</div></div>`}
function dashboardHero(){let dates=Object.keys(SCHEDULE.dates).sort(),latest=dates.at(-1),games=SCHEDULE.dates[latest]||[],finals=games.filter(x=>x.status==='Final').length,live=games.filter(x=>x.status==='Live').length;return `<section class="dashboard-hero"><div><span class="eyebrow">MLB COMMAND CENTER</span><h1>${LEAGUE.season} MLB ダッシュボード</h1><p>試合・順位・選手成績・Statcastを、ここからすぐ確認。</p></div><div class="dashboard-kpis"><div><small>最新日</small><strong>${latest||'—'}</strong></div><div><small>試合</small><strong>${games.length}</strong></div><div><small>終了 / ライブ</small><strong>${finals} / ${live}</strong></div><div><small>登録選手</small><strong>${fmt(LEAGUE.hitters.length+LEAGUE.pitchers.length,0)}</strong></div></div><nav class="quick-actions" aria-label="クイックアクセス"><button data-go="games">試合を見る</button><button data-go="standings">順位を見る</button><button data-go="batters">打者を探す</button><button data-go="pitchers">投手を探す</button><button data-go="sabermetrics">セイバー分析</button></nav></section>${favoritesPanel()}`}
function home(){let season=DATA.seasons.find(x=>x.season==state.season)||{},teamGames=Math.max(...LEAGUE.standings.map(x=>x.games||0),1),qualifiedPA=Math.round(teamGames*3.1);return `${dashboardHero()}<div class="dashboard-main"><div>${latestGames()}</div>${divisionSnapshot()}</div><section class="dashboard-overview"><div class="section-head"><div><span class="eyebrow">DATA COVERAGE</span><h2>${LEAGUE.season} データ概況</h2></div><span class="note">毎日自動更新</span></div><div class="stat-blocks"><div class="stat-block"><small>試合</small><strong>${fmt(season.games,0)}</strong></div><div class="stat-block"><small>投球</small><strong>${fmt(season.pitches,0)}</strong></div><div class="stat-block"><small>打者</small><strong>${fmt(LEAGUE.hitters.length,0)}</strong></div><div class="stat-block"><small>投手</small><strong>${fmt(LEAGUE.pitchers.length,0)}</strong></div></div></section>${weeklyMvp()}<div class="section-head"><div><span class="eyebrow">SEASON LEADERS</span><h2>${LEAGUE.season} シーズンリーダー</h2></div><button class="btn" data-go="standings">順位表</button></div><div class="data-grid">${leader('打率','hitters','avg',3,'plateAppearances',qualifiedPA)}${leader('本塁打','hitters','homeRuns',0)}${leader('OPS','hitters','ops',3,'plateAppearances',qualifiedPA)}${leader('打点','hitters','rbi',0)}${leader('防御率','pitchers','era',2,'inningsPitched',teamGames,true)}${leader('奪三振','pitchers','strikeOuts',0)}${leader('勝利','pitchers','wins',0)}${leader('セーブ','pitchers','saves',0)}</div>`}
function savedFavorites(){try{return JSON.parse(localStorage.getItem('mlb-data-lab-favorites'))||{players:[],teams:[]}}catch{return{players:[],teams:[]}}}
function favoriteKey(kind,id,type=''){return kind==='player'?`${type}:${id}`:String(id)}
function isFavorite(kind,id,type=''){let f=savedFavorites(),key=favoriteKey(kind,id,type);return (kind==='player'?f.players:f.teams).includes(key)}
function toggleFavorite(kind,id,type=''){let f=savedFavorites(),list=kind==='player'?f.players:f.teams,key=favoriteKey(kind,id,type),i=list.indexOf(key);i>=0?list.splice(i,1):list.push(key);localStorage.setItem('mlb-data-lab-favorites',JSON.stringify(f));render()}
function favoritesPanel(){let f=savedFavorites(),players=f.players.map(key=>{let [type,id]=key.split(':');return {...(LEAGUE[type]||[]).find(x=>x.id==id),type}}).filter(x=>x.id),teams=f.teams.map(id=>LEAGUE.standings.find(x=>x.team_id==id)).filter(Boolean);if(!players.length&&!teams.length)return `<div class="panel favorites-empty"><b>☆ お気に入り</b><span class="note">選手・球団詳細の☆を押すと、ここに固定できます。</span></div>`;return `<div class="panel favorites-panel"><div class="section-head"><h2>★ お気に入り</h2><span class="note">この端末に保存</span></div><div class="favorite-chips">${teams.map(x=>`<button data-open-team="${x.team_id}">${teamBadge(x.team_id,x.team,x.name)}${x.team}</button>`).join('')}${players.map(x=>`<button data-player="${x.id}" data-type="${x.type}">${teamBadge(x.team_id,x.team,x.team_name)}${x.name}</button>`).join('')}</div></div>`}
function teamGames(id){let list=[];Object.entries(SCHEDULE.dates).forEach(([date,games])=>games.forEach(g=>{if(g.away.id==id||g.home.id==id)list.push({...g,date})}));return list.sort((a,b)=>a.date.localeCompare(b.date))}
function openTeam(id){state.teamId=+id;state.returnView=state.view;state.view='standings';state.search='';$('#search').value='';showSearchResults();render()}
function teamDetail(){let t=LEAGUE.standings.find(x=>x.team_id==state.teamId);if(!t)return standings();let games=teamGames(t.team_id),finals=games.filter(x=>x.status==='Final'),recent=finals.slice(-10),upcoming=games.filter(x=>x.status!=='Final').slice(0,8),record=recent.reduce((a,g)=>{let side=g.away.id==t.team_id?g.away:g.home;a[side.winner?'w':'l']++;return a},{w:0,l:0}),hitters=LEAGUE.hitters.filter(x=>x.team_id==t.team_id).sort((a,b)=>(b.plateAppearances||0)-(a.plateAppearances||0)),pitchers=LEAGUE.pitchers.filter(x=>x.team_id==t.team_id).sort((a,b)=>Number(b.inningsPitched||0)-Number(a.inningsPitched||0)),pa=hitters.reduce((s,x)=>s+(x.plateAppearances||0),0),ip=pitchers.reduce((s,x)=>s+Number(x.inningsPitched||0),0),ops=pa?hitters.reduce((s,x)=>s+(x.ops||0)*(x.plateAppearances||0),0)/pa:0,era=ip?pitchers.reduce((s,x)=>s+(x.era||0)*Number(x.inningsPitched||0),0)/ip:0,inj=(LEAGUE.injuries||[]).filter(x=>x.team_id==t.team_id);return `<button class="btn back-btn" id="backTeam">← 順位表へ戻る</button><section class="team-hero">${teamBadge(t.team_id,t.team,t.name)}<div><span class="eyebrow">${t.league} · ${t.division}</span><h1>${t.name}</h1><p>${t.wins}勝 ${t.losses}敗 · 地区${t.rank}位</p></div><button class="favorite-btn ${isFavorite('team',t.team_id)?'on':''}" data-favorite-kind="team" data-favorite-id="${t.team_id}">${isFavorite('team',t.team_id)?'★ 登録済み':'☆ お気に入り'}</button></section><div class="team-kpis"><div><small>勝率</small><strong>${statFmt(t.pct,3)}</strong></div><div><small>直近10試合</small><strong>${record.w}-${record.l}</strong></div><div><small>得失点差</small><strong>${t.run_diff>0?'+':''}${t.run_diff}</strong></div><div><small>チームOPS</small><strong>${statFmt(ops,3)}</strong></div><div><small>チームERA</small><strong>${statFmt(era,2)}</strong></div><div><small>プレーオフ確率</small><strong>${statFmt(t.playoff_pct,1)}%</strong></div></div><div class="grid2"><div class="panel"><h2>得失点推移</h2><div id="teamRunChart" class="chart"></div></div><div class="panel"><h2>予測</h2><div class="prediction"><strong>${statFmt(t.playoff_pct,1)}%</strong><span>プレーオフ進出確率</span><small>予測勝利 ${statFmt(t.projected_wins,1)}勝</small></div><p class="note">現在の勝敗と得失点から5,000回シミュレーションした独自推定です。公式予測ではありません。</p></div></div><div class="grid2"><div class="panel"><h2>直近の結果</h2><div class="mini-games">${recent.reverse().map(g=>gameCard(g,true)).join('')}</div></div><div class="panel"><h2>今後の日程</h2><div class="mini-games">${upcoming.map(g=>gameCard(g,true)).join('')||'<p class="note">予定なし</p>'}</div></div></div><div class="panel"><h2>怪我人・登録状況</h2>${inj.length?`<div class="injury-list">${inj.map(x=>`<div><b>${x.name}</b><span>${x.position||'—'}</span><strong>${x.status}</strong></div>`).join('')}</div>`:'<p class="note">現在取得できる負傷者情報はありません。</p>'}</div><div class="grid2"><div class="panel"><h2>主要打者</h2>${teamRosterTable(hitters.slice(0,12),'hitters')}</div><div class="panel"><h2>主要投手</h2>${teamRosterTable(pitchers.slice(0,12),'pitchers')}</div></div>`}
function teamRosterTable(list,type){let hitting=type==='hitters';return `<div class="tablewrap"><table class="official-table"><thead><tr><th>選手</th><th>${hitting?'PA':'IP'}</th><th>${hitting?'OPS':'ERA'}</th><th>${hitting?'HR':'K'}</th></tr></thead><tbody>${list.map(x=>`<tr><td><button class="player-link" data-player="${x.id}" data-type="${type}">${x.name}</button></td><td>${statFmt(x[hitting?'plateAppearances':'inningsPitched'],1)}</td><td>${statFmt(x[hitting?'ops':'era'],hitting?3:2)}</td><td>${statFmt(x[hitting?'homeRuns':'strikeOuts'],0)}</td></tr>`).join('')}</tbody></table></div>`}
function teamDirectory(){let leagues={AL:[],NL:[]};LEAGUE.standings.forEach(x=>leagues[playerLeague(x)].push(x));return `<details class="panel team-key"><summary>30球団の略称・アイコン一覧</summary><p class="note">公式ロゴではなく、このサイト独自の識別アイコンです。</p><div class="team-key-leagues">${Object.entries(leagues).map(([league,teams])=>`<section><h3>${league==='AL'?'アメリカン・リーグ':'ナショナル・リーグ'}</h3><div class="team-key-grid">${teams.sort((a,b)=>a.team.localeCompare(b.team)).map(x=>`<div class="team-key-item">${teamBadge(x.team_id,x.team,x.name)}<span><b>${x.team}</b><small>${x.name}</small></span></div>`).join('')}</div></section>`).join('')}</div></details>`}
