function sabermetrics(){let s=LEAGUE.sabermetrics||{},teamGames=Math.max(...LEAGUE.standings.map(x=>x.games||0),1),pa=Math.round(teamGames*3.1),hit=state.saberSide==='hitters';return `<div class="saber-hero"><div><span class="eyebrow">ANALYST VIEW</span><h1>${LEAGUE.season} セイバーメトリクス</h1><p>勝敗の裏側を、平均との比較で読む。</p></div><button class="guide-link" data-go="method">指標の意味を見る →</button></div><section class="saber-section"><div class="saber-title"><div><span class="eyebrow">LEAGUE BASELINE</span><h2>まずはリーグ平均</h2></div><span class="note">選手評価のものさし</span></div><div class="kpis saber-baselines"><div class="kpi"><span>wOBA</span><b>${statFmt(s.league_woba,3)}</b><small>打者の総合攻撃力</small></div><div class="kpi"><span>ERA</span><b>${statFmt(s.league_era,2)}</b><small>実際の防御率</small></div><div class="kpi"><span>FIP</span><b>${statFmt(s.league_fip,2)}</b><small>守備非依存の投手評価</small></div><div class="kpi"><span>FIP定数</span><b>${statFmt(s.fip_constant,3)}</b><small>当年環境への調整値</small></div></div></section><section class="saber-section"><div class="saber-title"><div><span class="eyebrow">LEADERBOARD</span><h2>${hit?'打者':'投手'}トップ5</h2></div><span class="swipe-note">指標を横にスワイプ</span></div><div class="segmented" role="group" aria-label="打者と投手を切り替え"><button class="${hit?'on':''}" data-saber="hitters">打者</button><button class="${hit?'':'on'}" data-saber="pitchers">投手</button></div><div class="data-grid saber-leaders">${hit?`${leader('wOBA｜総合攻撃力','hitters','woba',3,'plateAppearances',pa)}${leader('wRAA｜平均比の得点価値','hitters','wraa',1,'plateAppearances',pa)}${leader('ISO｜長打力','hitters','iso',3,'plateAppearances',pa)}`:`${leader('FIP｜守備非依存評価','pitchers','fip',2,'inningsPitched',teamGames,true)}${leader('K-BB%｜支配力','pitchers','k_bb_pct',1,'inningsPitched',teamGames)}${leader('Whiff%｜空振り率','pitchers','whiff_pct',1,'inningsPitched',40)}`}</div></section><section class="saber-section"><div class="saber-title"><div><span class="eyebrow">PLAYER MAP</span><h2>${hit?'打者：長打力 × 総合攻撃力':'投手：支配力 × FIP'}</h2></div></div><div class="panel saber-chart-panel"><div id="${hit?'hitterSaberChart':'pitcherSaberChart'}" class="chart"></div><p class="chart-reading">${hit?'右上ほど、長打力と総合的な得点貢献が高い':'右下ほど、三振と四球の差が大きくFIPも優秀'}</p></div></section><details class="panel saber-method"><summary>計算方法と注意点</summary><p><b>${hit?'wOBA':'FIP'}</b>${hit?'は結果ごとに得点価値を重み付け。wRAAはリーグ平均より生み出した推定得点、ISOは長打率−打率です。':'は本塁打・四球・死球・奪三振から評価。FIP指数はリーグ平均を100とし、低いほど優秀です。'}</p><p class="note">球場補正を要するwRC+・WARは未掲載です。詳しい数式は「指標」ページに掲載しています。</p></details>`}
function drawSaberCharts(){let teamGames=Math.max(...LEAGUE.standings.map(x=>x.games||0),1),hitters=LEAGUE.hitters.filter(x=>x.plateAppearances>=teamGames*3.1&&x.woba!=null&&x.iso!=null),pitchers=LEAGUE.pitchers.filter(x=>Number(x.inningsPitched)>=teamGames&&x.fip!=null&&x.k_bb_pct!=null),layout={margin:{t:10,r:12,b:48,l:52},hovermode:'closest',paper_bgcolor:'transparent',plot_bgcolor:'transparent',font:{color:getComputedStyle(document.documentElement).getPropertyValue('--ink').trim()||'#16202a'}};if($('#hitterSaberChart'))Plotly.newPlot('hitterSaberChart',[{type:'scatter',mode:'markers',x:hitters.map(x=>x.iso),y:hitters.map(x=>x.woba),text:hitters.map(x=>`${x.name} (${x.team})`),customdata:hitters.map(x=>x.homeRuns),marker:{size:hitters.map(x=>Math.max(7,Math.sqrt(x.homeRuns||0)*2.2)),color:hitters.map(x=>x.wraa),colorscale:'RdBu',showscale:true,colorbar:{title:'wRAA',thickness:12}},hovertemplate:'%{text}<br>ISO %{x:.3f}<br>wOBA %{y:.3f}<br>HR %{customdata}<extra></extra>'}],{...layout,xaxis:{title:'ISO',gridcolor:'#94a3b833'},yaxis:{title:'wOBA',gridcolor:'#94a3b833'}},{responsive:true,displayModeBar:false});if($('#pitcherSaberChart'))Plotly.newPlot('pitcherSaberChart',[{type:'scatter',mode:'markers',x:pitchers.map(x=>x.k_bb_pct),y:pitchers.map(x=>x.fip),text:pitchers.map(x=>`${x.name} (${x.team})`),customdata:pitchers.map(x=>x.inningsPitched),marker:{size:pitchers.map(x=>Math.max(7,Math.sqrt(Number(x.inningsPitched)||0)*1.5)),color:pitchers.map(x=>x.fip_index),colorscale:'RdYlBu',reversescale:true,showscale:true,colorbar:{title:'FIP指数',thickness:12}},hovertemplate:'%{text}<br>K-BB% %{x:.1f}<br>FIP %{y:.2f}<br>IP %{customdata}<extra></extra>'}],{...layout,xaxis:{title:'K-BB%',gridcolor:'#94a3b833'},yaxis:{title:'FIP',autorange:'reversed',gridcolor:'#94a3b833'}},{responsive:true,displayModeBar:false})}
const officialCols={hitters:[['name','選手'],['team','TEAM'],['gamesPlayed','G'],['plateAppearances','PA'],['avg','AVG'],['obp','OBP'],['slg','SLG'],['ops','OPS'],['iso','ISO'],['bb_pct','BB%'],['k_pct','K%'],['woba','wOBA'],['wraa','wRAA'],['babip','BABIP'],['homeRuns','HR'],['rbi','RBI'],['runs','R'],['hits','H'],['stolenBases','SB']],pitchers:[['name','投手'],['team','TEAM'],['gamesPlayed','G'],['gamesStarted','GS'],['wins','W'],['losses','L'],['era','ERA'],['fip','FIP'],['fip_index','FIP指数'],['inningsPitched','IP'],['k_pct','K%'],['bb_pct','BB%'],['k_bb_pct','K-BB%'],['whiff_pct','Whiff%'],['babip','BABIP'],['whip','WHIP'],['strikeoutsPer9Inn','K/9'],['walksPer9Inn','BB/9'],['homeRunsPer9','HR/9'],['saves','SV'],['holds','HLD']]};
function sortedOfficial(type){let sorting=state.sort[type];return [...filteredOfficial(type)].sort((a,b)=>{let av=a[sorting.key],bv=b[sorting.key];if(av==null)return 1;if(bv==null)return-1;return sorting.dir*(typeof av==='string'?av.localeCompare(bv):Number(av)-Number(bv))})}
function officialTable(type){let allCs=officialCols[type],visible=new Set(state.visibleCols[type]),cs=allCs.filter(c=>visible.has(c[0])),sorting=state.sort[type],allData=sortedOfficial(type),pages=Math.max(1,Math.ceil(allData.length/state.pageSize));state.page[type]=Math.min(Math.max(1,state.page[type]),pages);let start=(state.page[type]-1)*state.pageSize,data=allData.slice(start,start+state.pageSize),teams=[...LEAGUE.standings].sort((a,b)=>a.team.localeCompare(b.team)),range=allData.length?`${start+1}〜${Math.min(start+state.pageSize,allData.length)}人`:'0人';return `<div class="panel"><div class="section-head"><h2>${LEAGUE.season} ${type==='hitters'?'打者':'投手'}シーズン成績</h2><span class="note">全${allData.length}人中 ${range} · 50人ずつ表示</span></div><div class="table-filters"><label>球団 <select id="teamFilter"><option value="">全30球団</option>${teams.map(x=>`<option value="${x.team}" ${state.teamFilter===x.team?'selected':''}>${x.team} · ${x.name}</option>`).join('')}</select></label><label class="check-filter"><input type="checkbox" id="qualified" ${state.qualified?'checked':''}> 規定到達のみ</label><details class="column-picker"><summary>表示列 ${cs.length}/${allCs.length}</summary><div>${allCs.map(c=>`<label><input type="checkbox" data-col="${c[0]}" data-col-type="${type}" ${visible.has(c[0])?'checked':''} ${['name','team'].includes(c[0])?'disabled':''}> ${c[1]}</label>`).join('')}</div></details><button class="btn" id="clearFilters">条件をクリア</button><button class="btn" id="exportCsv" data-type="${type}">CSV出力</button></div><div class="tablewrap"><table class="official-table"><thead><tr>${cs.map(c=>`<th><button class="sort-head" data-sort="${c[0]}" data-type="${type}">${c[1]}${sorting.key===c[0]?` <span>${sorting.dir===-1?'▼':'▲'}</span>`:''}</button></th>`).join('')}</tr></thead><tbody>${data.map(r=>`<tr>${cs.map((c,i)=>`<td class="${i>1?'num':''}">${i===0?`<button class="player-link" data-player="${r.id}" data-type="${type}">${r.name}</button>`:c[0]==='team'?`<span class="team-with-badge">${teamBadge(r.team_id,r.team,r.team_name)}<b>${r.team||'—'}</b></span>`:statFmt(r[c[0]],3)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><nav class="pagination" aria-label="一覧ページ"><button data-page="1" data-page-type="${type}" ${state.page[type]===1?'disabled':''}>« 最初</button><button data-page="${state.page[type]-1}" data-page-type="${type}" ${state.page[type]===1?'disabled':''}>‹ 前</button><span>${state.page[type]} / ${pages}ページ</span><button data-page="${state.page[type]+1}" data-page-type="${type}" ${state.page[type]===pages?'disabled':''}>次 ›</button><button data-page="${pages}" data-page-type="${type}" ${state.page[type]===pages?'disabled':''}>最後 »</button></nav></div>`}
function exportOfficialCsv(type){let cs=officialCols[type],quote=v=>`"${String(v??'').replaceAll('"','""')}"`,csv=[cs.map(c=>quote(c[1])).join(','),...sortedOfficial(type).map(r=>cs.map(c=>quote(r[c[0]])).join(','))].join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`mlb-${LEAGUE.season}-${type}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function playerDetail(){let type=state.playerType,p=(LEAGUE[type]||[]).find(x=>x.id==state.playerId);if(!p)return'<div class="panel">選手が見つかりません。</div>';let advanced=(type==='hitters'?DATA.batters:DATA.pitchers).find(x=>(x.batter||x.pitcher)==p.id&&x.season==state.season),fields=type==='hitters'?[['試合','gamesPlayed'],['打席','plateAppearances'],['打率','avg'],['出塁率','obp'],['長打率','slg'],['OPS','ops'],['ISO','iso'],['BB%','bb_pct'],['K%','k_pct'],['wOBA','woba'],['wRAA','wraa'],['BABIP','babip'],['本塁打','homeRuns'],['打点','rbi'],['盗塁','stolenBases']]:[['登板','gamesPlayed'],['先発','gamesStarted'],['勝','wins'],['敗','losses'],['防御率','era'],['FIP','fip'],['FIP指数','fip_index'],['投球回','inningsPitched'],['K%','k_pct'],['BB%','bb_pct'],['K-BB%','k_bb_pct'],['Whiff%','whiff_pct'],['BABIP','babip'],['WHIP','whip'],['セーブ','saves']];let adv=advanced?(type==='hitters'?[['平均打球速度',advanced.avg_ev+' mph'],['平均角度',advanced.avg_la+'°'],['Hard-hit%',advanced.hard_hit_pct+'%'],['Barrel%',advanced.barrel_pct+'%'],['xwOBA',advanced.xwoba]]:[['平均球速',advanced.velo+' mph'],['平均回転',advanced.spin+' rpm'],['Whiff%',advanced.whiff_pct+'%'],['CSW%',advanced.csw_pct+'%'],['xwOBA',advanced.xwoba]]):[];return `<button class="btn back-btn" id="backPlayer">← 一覧へ戻る</button><div class="panel"><div class="player-hero"><div class="player-identity">${teamBadge(p.team_id,p.team,p.team_name)}<div><span class="player-team">${p.team_name||p.team||''} · ${p.position||''}</span><h1>${p.name}</h1><span class="note">MLB公式成績 + セイバー + Statcast</span></div></div></div><h2>シーズン成績・セイバー指標</h2><div class="stat-blocks">${fields.map(([l,k])=>`<div class="stat-block"><small>${l}</small><strong>${statFmt(p[k],3)}</strong></div>`).join('')}</div><h2>Statcast指標</h2>${adv.length?`<div class="stat-blocks">${adv.map(([l,v])=>`<div class="stat-block"><small>${l}</small><strong>${statFmt(v,3)}</strong></div>`).join('')}</div>`:'<p class="note">対象シーズンのStatcast指標はありません。</p>'}</div>`}
function findGame(pk){for(let [date,games] of Object.entries(SCHEDULE.dates)){let game=games.find(x=>x.game_pk==pk);if(game)return{date,game}}return null}
function openGame(pk){state.gamePk=+pk;state.returnView=state.view;state.view='game';render()}
function gameDetail(){let found=findGame(state.gamePk);return `<button class="btn back-btn" id="backGame">← 試合一覧へ戻る</button>${found?gameCard(found.game,true):''}<section id="gameBox" class="panel"><div class="loading-state"><b>ボックススコアを読み込み中…</b><span class="note">打者・投手の個人成績を取得しています</span></div></section>`}
function boxRows(team,type){return Object.values(team.players||{}).filter(p=>type==='batting'?Number(p.stats?.batting?.plateAppearances)>0:Number(p.stats?.pitching?.outs)>0).sort((a,b)=>type==='batting'?Number(a.battingOrder||9999)-Number(b.battingOrder||9999):0)}
function boxTable(team,type){let batting=type==='batting',cs=batting?[['atBats','AB'],['runs','R'],['hits','H'],['rbi','RBI'],['baseOnBalls','BB'],['strikeOuts','SO'],['homeRuns','HR']]:[['inningsPitched','IP'],['hits','H'],['runs','R'],['earnedRuns','ER'],['baseOnBalls','BB'],['strikeOuts','SO'],['homeRuns','HR'],['numberOfPitches','P']],rows=boxRows(team,type);return `<div class="box-section"><h3>${batting?'打撃成績':'投手成績'}</h3><div class="tablewrap"><table class="official-table box-table"><thead><tr><th>選手</th><th>POS</th>${cs.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${rows.map(p=>`<tr><td><button class="player-link" data-player="${p.person.id}" data-type="${batting?'hitters':'pitchers'}">${p.person.fullName}</button></td><td>${p.position?.abbreviation||'—'}</td>${cs.map(c=>`<td class="num">${statFmt(p.stats[type]?.[c[0]],1)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function renderBox(box){return `<div class="section-head"><div><h2>試合別個人成績</h2><span class="note">ボックススコア</span></div></div><div class="box-teams">${['away','home'].map(side=>{let t=box.teams[side],info=teamInfo(t.team.id,t.team.abbreviation,t.team.name),bat=t.teamStats?.batting||{};return `<section class="box-team"><div class="box-team-title">${teamBadge(info.id,info.abbr,info.name)}<div><h2>${info.name}</h2><span class="note">${bat.runs||0}得点 · ${bat.hits||0}安打 · ${bat.homeRuns||0}本塁打</span></div></div>${boxTable(t,'batting')}${boxTable(t,'pitching')}</section>`}).join('')}</div>`}
async function loadGameDetail(pk){let target=$('#gameBox');if(!target)return;try{let box=BOX_CACHE.get(pk);if(!box){let response=await fetch(`https://statsapi.mlb.com/api/v1/game/${pk}/boxscore`);if(!response.ok)throw new Error(`HTTP ${response.status}`);box=await response.json();BOX_CACHE.set(pk,box)}if(state.view==='game'&&state.gamePk==pk){target.innerHTML=renderBox(box);bindDynamic()}}catch(error){target.innerHTML=`<div class="error-state"><h2>試合詳細を取得できませんでした</h2><p class="note">通信状況を確認して、もう一度お試しください。</p><button class="btn" id="retryGame">再読み込み</button></div>`;$('#retryGame').onclick=()=>loadGameDetail(pk)}}
function trends(){return `<div class="panel"><h2>直近400日のリーグ推移</h2><div id="trendChart" class="chart"></div></div>`}
function quality(){let q=DATA.quality.filter(x=>x.season==state.season);return `<div class="panel"><h2>欠損率と観測品質</h2><pre>${JSON.stringify(q[0]||{},null,2)}</pre><p class="note">接触時EV欠損は計測対象となる打球に限定。欠損は必ずしも異常ではありません。</p></div>`}
function method(){let s=LEAGUE.sabermetrics||{};return `<div class="panel"><h2>セイバー・Statcast指標ガイド</h2><div class="method-grid"><section><h3>打者</h3><p><b>ISO</b>＝SLG−AVG。長打力を測ります。</p><p><b>BB% / K%</b>＝四球・三振÷打席。打席アプローチを示します。</p><p><b>wOBA</b>＝(0.69×非敬遠四球＋0.72×死球＋0.88×単打＋1.247×二塁打＋1.578×三塁打＋2.031×本塁打)÷対象打席。結果の得点価値を重み付けします。</p><p><b>wRAA</b>＝(wOBA−リーグwOBA)÷${s.woba_scale||1.25}×PA。平均より生み出した推定得点です。</p></section><section><h3>投手</h3><p><b>K-BB%</b>＝奪三振率−四球率。投手の支配力と制球を一つで見ます。</p><p><b>FIP</b>＝(13×HR＋3×(BB＋HBP)−2×K)÷IP＋定数。守備の影響を受けにくい結果から評価します。当年定数は${statFmt(s.fip_constant,3)}です。</p><p><b>FIP指数</b>＝FIP÷リーグFIP×100。100が平均、低いほど優秀です（球場補正なし）。</p></section><section><h3>Statcast</h3><p><b>Whiff%</b> 空振り÷スイング。<b>CSW%</b> 見逃し＋空振り÷全投球。</p><p><b>Hard-hit%</b> 95mph以上。<b>Barrel%</b> Statcastの最適打球帯。<b>xwOBA</b> 打球速度・角度等から推定した攻撃価値。</p></section></div><p class="note">球速・回転・変化量・打球品質・結果指標を併読し、母数、役割、球場、時代差を考慮してください。wRC+・WARは球場補正と守備・走塁モデルが必要なため未掲載です。</p></div>`}
function compare(){let type=state.compareType,list=[...(LEAGUE[type]||[])].sort((a,b)=>type==='hitters'?(b.plateAppearances||0)-(a.plateAppearances||0):Number(b.inningsPitched||0)-Number(a.inningsPitched||0));return `<div class="panel compare-panel"><div class="section-head"><div><span class="eyebrow">PLAYER COMPARE</span><h2>選手比較</h2></div><div class="segmented"><button class="${type==='hitters'?'on':''}" data-compare-type="hitters">打者</button><button class="${type==='pitchers'?'on':''}" data-compare-type="pitchers">投手</button></div></div><p class="note">最大5人を選択。レーダーは同ポジションではなく、MLB全選手内のパーセンタイル（高いほど優秀）です。</p><div class="compare-layout"><label>選手を選択<select id="cmp" multiple size="14">${list.map(x=>`<option value="${x.id}">${x.name} (${x.team})</option>`).join('')}</select></label><div><div id="cmpChart" class="chart"></div><div id="cmpSummary"></div></div></div></div>`}
function bindDynamic(){document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>openPlayer(b.dataset.player,b.dataset.type));document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>openGame(b.dataset.game));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.view=b.dataset.go;if(b.dataset.date)state.gameDate=b.dataset.date;render()});document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{let s=state.sort[b.dataset.type];if(s.key===b.dataset.sort)s.dir*=-1;else{s.key=b.dataset.sort;s.dir=['name','team'].includes(s.key)?1:-1}render()});if($('#teamFilter'))$('#teamFilter').onchange=e=>{state.teamFilter=e.target.value;render()};if($('#qualified'))$('#qualified').onchange=e=>{state.qualified=e.target.checked;render()};if($('#clearFilters'))$('#clearFilters').onclick=()=>{state.teamFilter='';state.qualified=false;state.search='';$('#search').value='';render()};if($('#exportCsv'))$('#exportCsv').onclick=e=>exportOfficialCsv(e.currentTarget.dataset.type);if($('#backPlayer'))$('#backPlayer').onclick=()=>{state.view=state.returnView||'home';render()};if($('#backGame'))$('#backGame').onclick=()=>{state.view=state.returnView||'games';render()}}
function render(){let v=state.view;$('#view').innerHTML=v==='home'?home():v==='games'?games():v==='game'?gameDetail():v==='standings'?standings():v==='batters'?officialTable('hitters'):v==='pitchers'?officialTable('pitchers'):v==='sabermetrics'?sabermetrics():v==='player'?playerDetail():v==='overview'?overview():v==='trends'?trends():v==='quality'?quality():v==='method'?method():v==='compare'?compare():table(v);let params=new URLSearchParams({share:'1',view:v,season:state.season});if(v==='games')params.set('date',state.gameDate);if(v==='game')params.set('game',state.gamePk);if(v==='player'){params.set('player',state.playerId);params.set('type',state.playerType)}if(v==='batters'||v==='pitchers'){let s=state.sort[v==='batters'?'hitters':'pitchers'];params.set('sort',s.key);params.set('dir',s.dir)}if(state.search)params.set('q',state.search);if(state.teamFilter)params.set('team',state.teamFilter);if(state.qualified)params.set('qualified','1');history.replaceState(null,'',`?${params}`);if(v==='overview'){let p=rows('pitch_types');Plotly.newPlot('pitchChart',[{type:'bar',x:p.map(x=>x.pitch_name),y:p.map(x=>x.usage_pct),marker:{color:'#c9282d'}}],{margin:{t:10},yaxis:{title:'使用率 %'}},{responsive:true})}if(v==='trends'){let d=DATA.daily;Plotly.newPlot('trendChart',[{x:d.map(x=>x.date),y:d.map(x=>x.velo),name:'球速'},{x:d.map(x=>x.date),y:d.map(x=>x.ev),name:'打球速度'}],{margin:{t:10},yaxis:{title:'mph'}},{responsive:true})}if(v==='sabermetrics')drawSaberCharts();bindSort();bindDynamic();if(v==='compare')$('#cmp').onchange=drawCompare;if(v==='games')$('#gameDate').onchange=e=>{state.gameDate=e.target.value;render()};if(v==='game')loadGameDetail(state.gamePk)}
function drawCompare(){let type=state.compareType,ids=[...$('#cmp').selectedOptions].slice(0,5).map(x=>+x.value),all=LEAGUE[type]||[],players=all.filter(x=>ids.includes(+x.id)),defs=type==='hitters'?[['ops','OPS',1],['woba','wOBA',1],['iso','ISO',1],['bb_pct','BB%',1],['k_pct','K%',-1]]:[['era','ERA',-1],['fip','FIP',-1],['k_bb_pct','K-BB%',1],['whiff_pct','Whiff%',1],['whip','WHIP',-1]],percentile=(key,value,dir)=>{let vals=all.map(x=>Number(x[key])).filter(Number.isFinite).sort((a,b)=>a-b),rank=vals.filter(x=>x<=Number(value)).length/Math.max(vals.length,1)*100;return Math.round(dir>0?rank:100-rank)};Plotly.newPlot('cmpChart',players.map(x=>({type:'scatterpolar',fill:'toself',name:x.name,theta:defs.map(d=>d[1]),r:defs.map(d=>percentile(d[0],x[d[0]],d[2]))})),{polar:{radialaxis:{visible:true,range:[0,100]}},margin:{t:30,r:30,b:30,l:30},paper_bgcolor:'transparent',font:{color:getComputedStyle(document.documentElement).getPropertyValue('--ink').trim()}},{responsive:true,displayModeBar:false});let summary=$('#cmpSummary');if(summary)summary.innerHTML=players.length?`<div class="tablewrap"><table class="official-table"><thead><tr><th>選手</th>${defs.map(d=>`<th>${d[1]}</th>`).join('')}</tr></thead><tbody>${players.map(x=>`<tr><td>${x.name}</td>${defs.map(d=>{let avg=all.reduce((s,p)=>s+(Number(p[d[0]])||0),0)/Math.max(all.filter(p=>Number.isFinite(Number(p[d[0]]))).length,1),diff=Number(x[d[0]])-avg;return `<td>${statFmt(x[d[0]],3)}<small class="metric-diff ${diff*d[2]>=0?'good':'bad'}">${diff>=0?'+':''}${statFmt(diff,2)} vs平均</small></td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="note">比較する選手を選んでください。</p>'}
function bindSort(){document.querySelectorAll('th[data-k]').forEach(th=>th.onclick=()=>{let key=state.view,arr=rows(key),k=th.dataset.k;arr.sort((a,b)=>(b[k]??'')>(a[k]??'')?1:-1);th.closest('.panel').outerHTML=table(key,arr);bindSort()})}
async function init(){try{[DATA,SCHEDULE,LEAGUE]=await Promise.all([fetch('data/analytics-summary.json').then(r=>{if(!r.ok)throw Error('summary');return r.json()}),fetch('data/schedule.json').then(r=>{if(!r.ok)throw Error('schedule');return r.json()}),fetch('data/league.json').then(r=>{if(!r.ok)throw Error('league');return r.json()})]);let q=new URLSearchParams(location.search);state.season=+(q.get('season')||Math.max(...DATA.seasons.map(x=>x.season)));state.view=q.get('view')||'home';state.playerId=+(q.get('player')||0)||null;state.playerType=q.get('type')||null;state.gamePk=+(q.get('game')||0)||null;state.search=q.get('q')||'';state.teamFilter=q.get('team')||'';state.qualified=q.get('qualified')==='1';if(['home','games','game','standings','batters','pitchers','sabermetrics','player'].includes(state.view))state.season=LEAGUE.season;if((state.view==='batters'||state.view==='pitchers')&&q.get('sort'))state.sort[state.view==='batters'?'hitters':'pitchers']={key:q.get('sort'),dir:+q.get('dir')||-1};if(analyticsViews.has(state.view))await ensureAnalytics();let dates=Object.keys(SCHEDULE.dates).sort(),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());state.gameDate=q.get('date')||dates.filter(d=>d<=today).pop()||dates.at(-1)||today;$('#season').innerHTML=DATA.seasons.map(x=>`<option ${x.season==state.season?'selected':''}>${x.season}</option>`).join('');$('#search').value=state.search;$('#updated').textContent=`更新 ${DATA.generated_at} · 公式成績 ${LEAGUE.generated_at.slice(0,10)}`;$('#season').onchange=e=>{state.season=+e.target.value;render()};$('#search').oninput=e=>{state.search=e.target.value;render()};$('#tabs').onclick=e=>{if(!e.target.dataset.view)return;state.view=e.target.dataset.view;if(['home','games','standings','batters','pitchers','sabermetrics'].includes(state.view)){state.season=LEAGUE.season;$('#season').value=state.season}document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('on',x.dataset.view==state.view));render()};$('#share').onclick=async()=>{await navigator.clipboard.writeText(location.href);$('#share').textContent='コピー済み';setTimeout(()=>$('#share').textContent='共有URL',1200)};$('#theme').onclick=()=>document.documentElement.toggleAttribute('data-theme');document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('on',x.dataset.view==state.view));render()}catch(error){$('#view').innerHTML='<div class="panel error-state"><h2>データを読み込めませんでした</h2><p>通信状況を確認して、ページを再読み込みしてください。</p><button class="btn" onclick="location.reload()">再読み込み</button></div>'}}
function leagueSwitch(){return `<div class="league-switch" role="group" aria-label="リーグを切り替え"><span>リーグ</span><button class="${state.leagueFilter===''?'on':''}" data-league="">MLB全体</button><button class="${state.leagueFilter==='AL'?'on':''}" data-league="AL">ア・リーグ</button><button class="${state.leagueFilter==='NL'?'on':''}" data-league="NL">ナ・リーグ</button></div>`}
function formatBaseballRates(){let labels=new Set(['AVG','OBP','SLG','OPS','ISO','wOBA','BABIP','xwOBA','勝率','打率','出塁率','長打率']);document.querySelectorAll('table').forEach(table=>{let heads=[...table.querySelectorAll('thead th')].map(x=>x.textContent.replace(/[▼▲]/g,'').trim());heads.forEach((label,i)=>{if(labels.has(label))table.querySelectorAll(`tbody tr td:nth-child(${i+1})`).forEach(td=>{if(Number(td.textContent)===0)td.textContent='.000'})})});document.querySelectorAll('.stat-block').forEach(block=>{if(labels.has(block.querySelector('small')?.textContent.trim())){let value=block.querySelector('strong');if(value&&Number(value.textContent)===0)value.textContent='.000'}});document.querySelectorAll('.leader-card').forEach(card=>{let label=card.querySelector('h3')?.textContent.split('｜')[0];if(labels.has(label))card.querySelectorAll('.metric').forEach(x=>{if(Number(x.textContent)===0)x.textContent='.000'})})}
function formatEraAndSpeeds(){let speedLabels=new Set(['EV','球速']);document.querySelectorAll('table').forEach(table=>{let heads=[...table.querySelectorAll('thead th')];heads.forEach((th,i)=>{let label=th.textContent.replace(/[▼▲]/g,'').trim();if(label==='ERA')table.querySelectorAll(`tbody tr td:nth-child(${i+1})`).forEach(td=>{let n=Number(td.textContent);if(Number.isFinite(n))td.textContent=n.toFixed(2)});if(speedLabels.has(label)){th.textContent=`${label} mph / km/h`;table.querySelectorAll(`tbody tr td:nth-child(${i+1})`).forEach(td=>{let n=Number(td.textContent);if(Number.isFinite(n))td.textContent=`${n.toFixed(1)} / ${(n*1.609344).toFixed(1)}`})}})});document.querySelectorAll('.stat-block').forEach(block=>{let label=block.querySelector('small')?.textContent.trim(),value=block.querySelector('strong');if(label==='防御率'&&value){let n=Number(value.textContent);if(Number.isFinite(n))value.textContent=n.toFixed(2)}});document.querySelectorAll('.kpi b,.stat-block strong').forEach(el=>{let m=el.textContent.match(/^(-?\d+(?:\.\d+)?) mph$/);if(m){let n=Number(m[1]);el.textContent=`${n.toFixed(1)} mph / ${(n*1.609344).toFixed(1)} km/h`}})}
function syncLeagueUrl(){let u=new URL(location.href);state.leagueFilter?u.searchParams.set('league',state.leagueFilter):u.searchParams.delete('league');state.teamId&&state.view==='standings'?u.searchParams.set('teamId',state.teamId):u.searchParams.delete('teamId');history.replaceState(null,'',u)}
async function navigateTo(view){if(analyticsViews.has(view)&&!DATA.batters){$('#view').innerHTML='<div class="panel loading-state"><b>分析データを読み込み中…</b><span class="note">初回だけ数秒かかる場合があります</span></div>';await ensureAnalytics()}state.view=view;if(['home','games','standings','batters','pitchers','sabermetrics'].includes(view)){state.season=LEAGUE.season;$('#season').value=state.season}document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('on',x.dataset.view===view));if($('#mobileNav'))$('#mobileNav').value=view;render()}
function mountLeagueSwitch(){if(document.querySelector('.league-switch')||!['home','batters','pitchers','sabermetrics'].includes(state.view))return;let target=state.view==='home'?[...document.querySelectorAll('.section-head')].find(x=>x.textContent.includes('シーズンリーダー')):state.view==='sabermetrics'?document.querySelector('.segmented'):document.querySelector('.table-filters');if(target)target.insertAdjacentHTML(state.view==='home'?'afterend':'beforebegin',leagueSwitch())}
document.addEventListener('click',e=>{let b=e.target.closest('[data-saber]');if(b){state.saberSide=b.dataset.saber;render()}let l=e.target.closest('[data-league]');if(l){state.leagueFilter=l.dataset.league;state.page.hitters=state.page.pitchers=1;render()}let p=e.target.closest('[data-page]');if(p&&!p.disabled){state.page[p.dataset.pageType]=+p.dataset.page;render();document.querySelector('.official-table')?.scrollIntoView({block:'start'})}if(e.target.closest('#clearFilters')){state.leagueFilter='';state.page.hitters=state.page.pitchers=1}});
document.addEventListener('click',e=>{let tab=e.target.closest('.tab[data-view]');if(tab){e.preventDefault();e.stopImmediatePropagation();navigateTo(tab.dataset.view)}},true);
document.addEventListener('change',e=>{if(e.target.id==='mobileNav')navigateTo(e.target.value);if(e.target.matches('[data-col]')){let type=e.target.dataset.colType,cols=new Set(state.visibleCols[type]);e.target.checked?cols.add(e.target.dataset.col):cols.delete(e.target.dataset.col);state.visibleCols[type]=officialCols[type].map(c=>c[0]).filter(k=>cols.has(k));render()}});
document.addEventListener('input',e=>{if(e.target.id==='search')showSearchResults()});
document.addEventListener('click',e=>{if(e.target.closest('#searchButton')){state.search=$('#search').value.trim();showSearchResults();$('#searchResults [data-first-result]')?.focus()}});
document.addEventListener('keydown',e=>{if(e.target.id==='search'&&e.key==='Enter'){e.preventDefault();$('#searchResults [data-first-result]')?.click()}if(e.target.id==='search'&&e.key==='Escape'){e.target.value='';state.search='';showSearchResults();render()}});
document.addEventListener('click',e=>{let team=e.target.closest('[data-search-team]');if(team){let row=LEAGUE.standings.find(x=>x.team===team.dataset.searchTeam);if(row)openTeam(row.team_id);return}let badge=e.target.closest('.team-badge');if(badge&&!e.target.closest('[data-player]')&&!e.target.closest('[data-search-team]')){openTeam(badge.dataset.teamId);return}let open=e.target.closest('[data-open-team]');if(open){openTeam(open.dataset.openTeam);return}let fav=e.target.closest('[data-favorite-kind]');if(fav){toggleFavorite(fav.dataset.favoriteKind,fav.dataset.favoriteId,fav.dataset.favoriteType||'');return}if(e.target.closest('#backTeam')){state.teamId=null;render();return}if(e.target.closest('#searchResults [data-player]')){state.search='';$('#search').value='';showSearchResults()}else if(!e.target.closest('.global-search')){$('#searchResults')?.classList.remove('open');$('#search')?.setAttribute('aria-expanded','false')}});
new MutationObserver(()=>requestAnimationFrame(()=>{document.querySelector('.tab.on')?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});if($('#mobileNav'))$('#mobileNav').value=state.view;mountLeagueSwitch();formatBaseballRates();formatEraAndSpeeds();syncLeagueUrl()})).observe(document.querySelector('#view'),{childList:true});
function addPlayerRanks(){if(state.view!=='player'||!state.playerId)return;let type=state.playerType,p=(LEAGUE[type]||[]).find(x=>x.id==state.playerId),blocks=document.querySelector('.player-hero')?.closest('.panel')?.querySelector('.stat-blocks');if(!p||!blocks||blocks.dataset.ranked)return;let keys=type==='hitters'?{'試合':'gamesPlayed','打席':'plateAppearances','打率':'avg','出塁率':'obp','長打率':'slg','OPS':'ops','ISO':'iso','BB%':'bb_pct','K%':'k_pct','wOBA':'woba','wRAA':'wraa','BABIP':'babip','本塁打':'homeRuns','打点':'rbi','盗塁':'stolenBases'}:{'登板':'gamesPlayed','先発':'gamesStarted','勝':'wins','敗':'losses','防御率':'era','FIP':'fip','FIP指数':'fip_index','投球回':'inningsPitched','K%':'k_pct','BB%':'bb_pct','K-BB%':'k_bb_pct','Whiff%':'whiff_pct','BABIP':'babip','WHIP':'whip','セーブ':'saves'},lower=new Set(type==='pitchers'?['losses','era','fip','fip_index','bb_pct','babip','whip']:[]),qualified=new Set(type==='hitters'?['avg','ops']:['era']),teamGames=x=>LEAGUE.standings.find(t=>t.team_id==x.team_id)?.games||0;blocks.querySelectorAll('.stat-block').forEach(block=>{let key=keys[block.querySelector('small')?.textContent.trim()],value=Number(p[key]);if(!key||!Number.isFinite(value))return;let eligible=x=>{if(!qualified.has(key))return true;return type==='hitters'?Number(x.plateAppearances)>=teamGames(x)*3.1:Number(x.inningsPitched)>=teamGames(x)},pool=(LEAGUE[type]||[]).filter(x=>eligible(x)&&Number.isFinite(Number(x[key]))),playerEligible=eligible(p);if(!playerEligible){block.insertAdjacentHTML('beforeend','<span class="stat-rank outside" title="規定未到達">規定外</span>');return}let better=pool.filter(x=>lower.has(key)?Number(x[key])<value:Number(x[key])>value).length,rank=better+1;block.insertAdjacentHTML('beforeend',`<span class="stat-rank" title="MLB順位（${pool.length}人中）">#${rank}</span>`)});blocks.dataset.ranked='1'}
function enhancePlayerDetail(){if(state.view!=='player'||!state.playerId)return;let hero=document.querySelector('.player-hero'),panel=hero?.closest('.panel');if(!hero||!panel||hero.querySelector('.favorite-btn'))return;hero.insertAdjacentHTML('beforeend',`<button class="favorite-btn ${isFavorite('player',state.playerId,state.playerType)?'on':''}" data-favorite-kind="player" data-favorite-id="${state.playerId}" data-favorite-type="${state.playerType}">${isFavorite('player',state.playerId,state.playerType)?'★ 登録済み':'☆ お気に入り'}</button>`);panel.insertAdjacentHTML('beforeend','<section class="player-splits"><h2>スプリット成績</h2><div id="playerSplits"><div class="loading-state"><b>左右・月別・球場別成績を読み込み中…</b></div></div></section>');loadPlayerSplits(state.playerId,state.playerType)}
async function loadPlayerSplits(id,type){let target=$('#playerSplits');if(!target)return;let key=`${id}-${type}-${LEAGUE.season}`;try{let result=PLAYER_SPLIT_CACHE.get(key),group=type==='hitters'?'hitting':'pitching';if(!result){let request=stats=>fetch(`https://statsapi.mlb.com/api/v1/people/${id}/stats?stats=${stats}&group=${group}&season=${LEAGUE.season}`).then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(j=>(j.stats?.[0]?.splits||[]));let [vl,vr,home,away,months]=await Promise.all([request('season&sitCodes=vl'),request('season&sitCodes=vr'),request('season&sitCodes=home'),request('season&sitCodes=away'),request('byMonth')]);result={situations:[['対左',vl[0]],['対右',vr[0]],['ホーム',home[0]],['ビジター',away[0]]],months};PLAYER_SPLIT_CACHE.set(key,result)}let cols=type==='hitters'?[['gamesPlayed','G'],['plateAppearances','PA'],['avg','AVG'],['obp','OBP'],['slg','SLG'],['ops','OPS']]:[['gamesPlayed','G'],['inningsPitched','IP'],['era','ERA'],['whip','WHIP'],['strikeOuts','K'],['baseOnBalls','BB']],make=(rows,label)=>`<div class="tablewrap"><table class="official-table split-table"><thead><tr><th>${label}</th>${cols.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${rows.map(([name,x])=>`<tr><td>${name}</td>${cols.map(c=>`<td>${statFmt(x?.stat?.[c[0]],c[0]==='era'?2:3)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;let months=result.months.sort((a,b)=>Number(a.month)-Number(b.month)).map(x=>[`${x.month}月`,x]);target.innerHTML=`<div class="grid2"><div><h3>左右・球場別</h3>${make(result.situations,'条件')}</div><div><h3>月別</h3>${make(months,'月')}</div></div><p class="note">MLB公式Stats APIから表示時に取得します。</p>`}catch{target.innerHTML='<p class="note">スプリット成績を取得できませんでした。時間を置いて再度お試しください。</p>'}}
function drawTeamRunChart(){if(state.view!=='standings'||!state.teamId||!$('#teamRunChart'))return;let diff=0,games=teamGames(state.teamId).filter(x=>x.status==='Final'),y=games.map(g=>{let own=g.away.id==state.teamId?g.away.score:g.home.score,opp=g.away.id==state.teamId?g.home.score:g.away.score;return diff+=(own||0)-(opp||0)});Plotly.newPlot('teamRunChart',[{x:games.map(g=>g.date),y,mode:'lines',line:{color:'#0f6d8c',width:3},fill:'tozeroy',name:'累積得失点差'}],{margin:{t:12,r:12,b:45,l:48},paper_bgcolor:'transparent',plot_bgcolor:'transparent',xaxis:{title:'日付'},yaxis:{title:'累積得失点差'}},{responsive:true,displayModeBar:false})}
document.addEventListener('click',e=>{let b=e.target.closest('[data-compare-type]');if(b){state.compareType=b.dataset.compareType;render()}});
new MutationObserver(()=>requestAnimationFrame(()=>{enhancePlayerDetail();addPlayerRanks();drawTeamRunChart()})).observe(document.querySelector('#view'),{childList:true});
const standingsList=standings;
function playoffRace(){let card=league=>`<div class="panel"><h3>${league==='AL'?'アメリカン・リーグ':'ナショナル・リーグ'}</h3><div class="playoff-list">${LEAGUE.standings.filter(x=>x.league===league).sort((a,b)=>(b.playoff_pct||0)-(a.playoff_pct||0)).map((x,i)=>`<button data-open-team="${x.team_id}"><span>${i+1}</span>${teamBadge(x.team_id,x.team,x.name)}<b>${x.team}</b><strong>${statFmt(x.playoff_pct,1)}%</strong><small>${statFmt(x.projected_wins,1)}勝予測</small></button>`).join('')}</div></div>`;return `<div class="section-head playoff-head"><div><span class="eyebrow">PLAYOFF RACE</span><h2>プレーオフ進出確率</h2></div><span class="note">独自5,000回シミュレーション</span></div><div class="grid2">${card('AL')}${card('NL')}</div><p class="note">現在の勝敗と得失点から推定。公式予測や賭けの助言ではありません。</p>`}
standings=function(){return state.teamId?teamDetail():standingsList()+playoffRace()};
init();
